save(335,dict(paragraphs=["Lopamudra Banerjee is a poet, author, editor and translator originally from Kolkata and based in Texas. She has translated Bengali fiction by Ashapurna Devi and Mallika Sengupta into English. In an interview with IPPL Journal, she describes translation as a meeting between another writer’s creation and a new readership, and her collaboration with Priscilla Rice, We Are What We Are, as an exploration of women’s voices, cultural roots and identity.","Her Kabita Live poems make memory and the act of writing inseparable. ‘Absence’ listens for the sounds left by people and moments that have vanished, finding the material of verse in what is missing. ‘True Love Meets Poetry’ brings love into contact with free verse, music and disorder, allowing estrangement as well as intimacy to shape the poem."],sources=[source('IPPL Journal — interview with Lopamudra Banerjee, April 2024','https://ippljournal.org/issue-5-april-2024/interview-of-lopamudra-banerjee/',['Kolkata/Texas biography; Bengali translations; first-person account of translation and collaboration with Priscilla Rice']),source('Black Eagle Books — We Are What We Are','https://www.blackeaglebooks.org/product/we-are-what-we-are/',['Joint authors Lopamudra Banerjee and Priscilla Rice; 2022 English collection, ISBN 9781645602910'],'search_index_page; direct retrieval failed')],books=[dict(title='We Are What We Are',detail='With Priscilla Rice · author interview in IPPL Journal',url='https://ippljournal.org/issue-5-april-2024/interview-of-lopamudra-banerjee/')],identity_match='Kolkata-to-Texas background, Priscilla Rice collaboration and two distinctive Bengali translation titles match supplied biography.',poems_read=[dict(id=771,title='Absence',basis='Full original read: memories, grief, music, absence and embodied verse.'),dict(id=411,title='True Love Meets Poetry',basis='Full original read: love and free verse, rhythm, estrangement, wounds, music and rebirth.')],limitations=['Changing book totals and awards omitted; no award organizer confirmation sought for omitted claims.','Publisher product text indexed but direct retrieval failed; book card deliberately links the verified author interview.','Poetic grief and embodied imagery not assigned to particular personal events.'],next_action='Independent author/editor factual and literary review.'))
